const app=document.getElementById('app'),nav=document.getElementById('nav');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const card=(e,base='lore')=>`<a class="tile" href="#/${base}/${encodeURIComponent(e.id)}"><span class="tile-glyph" aria-hidden="true">✧</span><small>${esc(e.type)}</small><h3>${esc(e.title)}</h3><p>${esc(e.summary)}</p><span class="tile-more">Open record →</span></a>`;
const wrapper=(eyebrow,title,body)=>`<section class="shell section archive-section"><div class="page-heading"><div class="kicker">${esc(eyebrow)}</div><h1 class="title">${esc(title)}</h1><div class="ornament" aria-hidden="true">✦</div></div>${body}</section>`;
const paper=(eyebrow,title,content)=>`<article class="paper" aria-label="${esc(title)}"><div class="paper-corner" aria-hidden="true">✧</div><div class="kicker">${esc(eyebrow)}</div><h1>${esc(title)}</h1><div class="paper-rule" aria-hidden="true">✦</div>${content}</article>`;
const related=e=>e.related?.length?`<aside class="continue-reading" aria-label="Continue exploring"><h2>Follow your curiosity</h2><div class="related-paths">${e.related.map(id=>entries.find(x=>x.id===id)).filter(Boolean).map(x=>`<a href="#/lore/${x.id}"><strong>${esc(x.title)}</strong><span>${esc(x.summary)}</span><small>Explore →</small></a>`).join('')}</div></aside>`:'';
function levelPreview(id){const e=entries.find(x=>x.id===id);const anchors={'upper-heights':'read-upper','middle-heights':'read-middle',deepwater:'read-deepwater'};return `<h3>${esc(e.title)}</h3><p>${esc(e.summary)}</p><div class="level-actions"><a class="text-link" href="#${anchors[id]}">See this level’s illustration ↓</a><a class="text-link" href="#/lore/${e.id}">Read about ${esc(e.title)} →</a></div>`}
document.addEventListener('click',event=>{const choice=event.target.closest('[data-level]');if(!choice)return;const id=choice.dataset.level;if(!['upper-heights','middle-heights','deepwater'].includes(id))return;document.querySelectorAll('[data-level]').forEach(button=>button.setAttribute('aria-pressed',String(button===choice)));document.getElementById('level-preview').innerHTML=levelPreview(id)});
const page={
 '/':()=>`<section class="single-opening original-hero" id="read-arrival"><div class="shell opening-content"><p class="novel-status">A DARK FANTASY NOVEL IN DEVELOPMENT</p><h1>Where the Light Falls</h1><p class="opening-line">Two years after an uprising, a brother is still searching for his sister.</p><div class="hero-entry"><a class="btn primary" href="#read-premise">Discover the story <span aria-hidden="true">↓</span></a></div><button type="button" class="hero-view-full" data-hero-full="assets/images/the-grand-crossing.png" aria-label="View the Grand Crossing illustration full size">View the artwork <span aria-hidden="true">↗</span></button></div></section><div class="journey"><section class="shell section story-premise" id="read-premise"><div class="kicker">The story</div><h2>He is searching for Mira.<br>She wanted a life of her own.</h2><p>Approximately two years after an uprising, Elias Varek still believes his younger sister may be alive. He keeps asking questions in the city where they grew up—a crowded Gothic metropolis built across an immense canyon.</p><p>Before the uprising, protecting Mira had shaped his life. But she had friendships, ambitions and choices of her own. His search brings him closer to a life he could never entirely know.</p><p class="reader-promise">A dark fantasy novel about family, independence and belonging. Currently in development.</p><a class="text-link" href="#/story">Explore the story without major spoilers →</a></section><section class="shell reader-paths" aria-labelledby="reader-paths-title"><div class="kicker">Your way into the novel</div><h2 id="reader-paths-title">What draws you in?</h2><p>Start with a question. Follow what interests you.</p><div class="reader-path-grid"><a href="#/story" class="reader-path"><small>The story</small><h3>Why is Elias still searching?</h3><p>Begin with the missing sister, the brother who keeps looking, and the bond between them.</p><span>Discover the premise →</span></a><a href="#/characters" class="reader-path"><small>The people</small><h3>Who matters beyond the siblings?</h3><p>Meet river traders, old friends and an official caught between duty and conscience.</p><span>Meet the characters →</span></a><a href="#read-city" class="reader-path"><small>The city</small><h3>Who gets to live in the light?</h3><p>Descend through crowded canyon neighborhoods and discover the rules that divide them.</p><span>Explore the three levels ↓</span></a></div></section><section class="shell section journey-ending" id="read-people"><div class="kicker">The characters · Elias and Mira</div><h2>Two lives at the heart of the city.</h2><div class="sibling-portraits"><figure class="journey-art story-portrait"><img src="Elias%20Above%20the%20Misty%20Cliff%20City.png" alt="Elias Varek, a lean young man with tousled chestnut hair, resting beneath a stone arch overlooking the canyon city." loading="lazy" decoding="async" fetchpriority="low"><figcaption>Elias Varek · The watchful older brother.</figcaption></figure><figure class="journey-art story-portrait"><img src="Mira%20Overlooking%20the%20Lanternlit%20Canyon%20City.png" alt="Mira Varek, a freckled teenage girl with loosely tied dark hair, looking toward the bridges and lantern-lit canyon river." loading="lazy" decoding="async" fetchpriority="low"><figcaption>Mira Varek · Curious about the world beyond.</figcaption></figure></div><p>Elias is watchful, protective, and reluctant to let go. Mira is curious, sociable, and determined to make her own choices. Their bond gives this immense city a human heart.</p><div class="actions"><a class="btn primary" href="#/lore/elias">Meet Elias →</a><a class="btn" href="#/lore/mira">Meet Mira →</a></div></section><section class="shell section" id="read-shelter"><div class="kicker">Their home · Beneath the viaducts</div><h2>Beneath the great bridges</h2><figure class="journey-art lore-art"><img src="Candlelit%20Medieval%20Stone%20Hideout.png" alt="An exploratory image of a compact vaulted stone shelter with two beds, a shared worktable and a lantern." loading="lazy" decoding="async"><figcaption>Elias and Mira’s home beneath the viaducts · Interior concept.</figcaption></figure><p>Within the stone foundations of the great viaducts, Elias and Mira made their home in a concealed vaulted shelter. Beneath structures that carry a city, the siblings had a place of their own.</p></section><div class="shell city-intro" id="read-city"><div class="kicker">The world they call home</div><h2>Three levels. Countless lives.</h2><p>One Gothic metropolis spans both rims of an extremely deep, narrow canyon. Inside it, homes and workshops cling to steep inhabited walls. Descend far enough and little direct sunlight reaches you—but the neighborhoods remain full of life.</p></div><section class="shell level-explorer" aria-labelledby="level-explorer-title"><div class="kicker">Inside the canyon</div><h2 id="level-explorer-title">Choose a level to explore.</h2><div class="level-choices" role="group" aria-label="Choose a Lower City level"><button type="button" data-level="upper-heights" aria-pressed="true">Upper Heights</button><button type="button" data-level="middle-heights" aria-pressed="false">Middle Heights</button><button type="button" data-level="deepwater" aria-pressed="false">Deepwater</button></div><div class="level-preview" id="level-preview" aria-live="polite" aria-atomic="true">${levelPreview('upper-heights')}</div><p class="explorer-note">Three views of one city. The illustrations explore its atmosphere, not an exact map.</p></section><section class="journey-chapter shell" id="read-deepwater" aria-labelledby="deepwater-title"><figure class="journey-art"><img src="assets/images/districts/deepwater-concept-07.png" alt="Deepwater concept art: crowded timber docks, cargo and moored boats beside a shaded river, enclosed by steep inhabited walls and high stone bridges." loading="lazy" decoding="async" fetchpriority="low"><figcaption>Deepwater · A working riverfront at the lowest inhabited level.</figcaption></figure><div class="journey-copy"><div class="kicker">The city · Deepwater</div><h2 id="deepwater-title">Life where little sunlight reaches.</h2><p>Deepwater is the lowest inhabited level, where docks, warehouses, markets and homes gather beside the river. Boats carry people and goods to settlements beyond the city. Little direct sunlight reaches these depths, but the riverfront is part of a crowded, working community—not simply a place to pass through.</p><a class="text-link" href="#/lore/deepwater">Discover life along the river →</a></div></section><section class="journey-chapter shell reverse" id="read-middle" aria-labelledby="middle-title"><figure class="journey-art"><img src="assets/images/districts/middle-heights-concept-07.png" alt="Middle Heights concept art: homes, an open workshop, a produce stall and neighbors sharing a terrace above the distant river in a deep, narrow canyon." loading="lazy" decoding="async" fetchpriority="low"><figcaption>Middle Heights · A glimpse of neighborhood life within the canyon walls.</figcaption></figure><div class="journey-copy"><div class="kicker">The city · Middle Heights</div><h2 id="middle-title">A neighborhood within the walls.</h2><p>Between Deepwater and Upper Heights, homes, workshops, shared spaces and neighborhood commerce fill the canyon’s middle inhabited level. Generations of residents have built their lives along natural ledges and reinforced terraces. Beneath the monumental crossings, work, trade and ordinary companionship belong to a crowded urban society of its own.</p><a class="text-link" href="#/lore/middle-heights">Explore Middle Heights →</a></div></section><section class="journey-chapter shell" id="read-upper" aria-labelledby="upper-title"><figure class="journey-art"><img src="assets/images/districts/upper-heights-concept-07.png" alt="Upper Heights concept art: traders unloading a cart at a crowded market below a guarded entrance, with densely inhabited canyon walls and monumental bridges beyond." loading="lazy" decoding="async" fetchpriority="low"><figcaption>Upper Heights · Lower City trade approaching guarded access above.</figcaption></figure><div class="journey-copy"><div class="kicker">The city · Upper Heights</div><h2 id="upper-title">Close to the city above.</h2><p>Upper Heights is the highest of the three Lower City levels, connecting its routes and trade with the Upper City economy. One guarded gate controls authorized direct entry above. The city depends on the labor and commerce below it, yet economic success alone does not grant Upper City citizenship or the right to live there.</p><a class="text-link" href="#/lore/upper-heights">Explore Upper Heights →</a><p><a class="text-link" href="#/lore/upper-access">Approach the Upper City gate →</a></p></div></section><section class="shell section supporting-cast" id="read-supporting"><div class="kicker">People of the wider world</div><h2>Lives beyond the siblings.</h2><p>Elias and Mira's city is full of people with responsibilities, loyalties and contradictions of their own. These three belong to different corners of that world.</p><p><a class="text-link" href="#/characters">Meet the wider cast →</a></p><div class="supporting-cast-grid"><a class="supporting-card" href="#/lore/registrar"><small>Institutions</small><h3>The Registrar</h3><p>An official whose duties and conscience do not always agree.</p><span>Meet the Registrar →</span></a><a class="supporting-card" href="#/lore/river-captain"><small>The waterways</small><h3>The River Captain</h3><p>A fiercely independent captain whose care for the crew comes with contradictions.</p><span>Meet the Captain →</span></a><a class="supporting-card" href="#/lore/workshop-keeper"><small>Community</small><h3>The Workshop Keeper</h3><p>Repair work, shared food and ordinary life in the Lower City.</p><span>Visit the workshop →</span></a></div></section><section class="shell section lore-optional" id="read-lore-optional"><div class="kicker">For the lore-curious · Optional</div><h2>There is more beneath the surface.</h2><p>Curious about the world behind the story? Open any topic below, or search the full lore archive. You can explore the novel without reading every record.</p><p><a class="text-link" href="#/lore">Browse all 30 lore entries →</a></p><a class="text-link" href="#read-more">Continue to the project ↓</a></section><section class="shell section lore-passage" id="read-origins"><div class="kicker">World lore · Origins</div><details class="lore-disclosure"><summary><h2>How the canyon became a city</h2><span aria-hidden="true">+</span></summary><div class="lore-disclosure-body"><blockquote class="chapter-quote">Before the city rose, someone had to cross.</blockquote><p>The first permanent stone crossing was financed by trading families and landholders. Its tolls helped shape the power of those who built it. Workers settled around the crossing; families, craftspeople and merchants followed. Over generations, the Lower City grew into permanent neighborhoods with their own communities, not a single planned slum.</p></div></details></section><section class="shell section lore-passage" id="read-society"><div class="kicker">World lore · Labor and belonging</div><details class="lore-disclosure"><summary><h2>Who keeps the crossings standing?</h2><span aria-hidden="true">+</span></summary><div class="lore-disclosure-body"><aside class="chapter-aside"><span class="aside-label">The city below</span><strong class="aside-title">A bridge connects places. It does not grant everyone the same rights.</strong></aside><p>The lower levels provide essential labor, maintenance, manufacturing and river trade. The Upper City benefits from control of the main crossings and regulated commerce. At Upper Heights, one guarded gate controls the direct legal entry from Lower City to Upper City. Authorized workers may pass, but must leave when their permitted hours end.</p><p>Citizenship is distinct from wealth or a work permit. It can be inherited through a legally recognized and registered citizen parent, while outsiders face an expensive application process requiring a sponsor. Marriage and a relative's admission do not automatically grant citizenship.</p></div></details></section><section class="shell section lore-passage" id="read-power"><div class="kicker">World lore · Power</div><details class="lore-disclosure"><summary><h2>The people who make the rules</h2><span aria-hidden="true">+</span></summary><div class="lore-disclosure-body"><blockquote class="chapter-quote">Power began with a crossing. It did not end there.</blockquote><p>A council that grew from crossing financiers and property owners governs trade, infrastructure and disputes. Its members disagree over security, commerce and reform. Upper-city privileges have outlasted the temporary workforce they were originally designed around; people on both sides of the divide hold differing views about what should change.</p></div></details></section><section class="shell section lore-passage" id="read-everyday"><div class="kicker">World lore · Everyday life</div><details class="lore-disclosure"><summary><h2>Small things matter here</h2><span aria-hidden="true">+</span></summary><div class="lore-disclosure-body"><aside class="chapter-aside"><span class="aside-label">An everyday object</span><strong class="aside-title">The Arch</strong><p>A bronze coin named for the structures that shaped the city.</p></aside><p>An architectural arch marks the everyday bronze coin that bears its name. Crossings shape more than the skyline here: they are part of the city’s daily work, trade and ordinary possessions.</p></div></details></section><section class="shell section journey-outro" id="read-more"><div class="kicker">The story begins here</div><figure class="world-logo-art"><img src="Where%20the%20Light%20Falls_%20Gothic%20Cityscape.png" alt="Where the Light Falls — gilded gothic wordmark against a detailed canyon cityscape" loading="lazy" decoding="async" fetchpriority="low"></figure><h2>A novel taking shape. A world to explore.</h2><p>Where the Light Falls is a dark fantasy novel in development, centered on family, independence and the lives people build within unequal systems. Meet Elias and Mira, explore the canyon, and return as the story and its visual world take shape.</p><div class="actions"><a class="btn primary" href="#/lore/elias">Meet Elias →</a><a class="btn" href="#/lore/mira">Meet Mira →</a><a class="btn" href="#/lore">Discover the lore →</a></div><aside class="art-process" aria-labelledby="art-process-title"><h3 id="art-process-title">Imagining the canyon</h3><p>The illustrations are concept art developed with AI assistance and iterative art direction. They explore the scale, light and inhabited life of <em>Where the Light Falls</em>. Individual buildings, clothing and layouts are visual interpretations rather than fixed maps or final designs.</p></aside><div class="world-paths"><a class="tile" href="#/world"><small>World</small><h3>Explore the City</h3><p>Geography, neighborhoods and society.</p></a><a class="tile" href="#/characters"><small>People</small><h3>Meet the Characters</h3><p>Spoiler-safe introductions.</p></a><a class="tile" href="#/chronology"><small>History</small><h3>The First Crossing</h3><p>How a crossing shaped a metropolis.</p></a></div></section></div>`,
 '/journey':()=>`<section class="shell section"><h1>The illustrated journey has moved.</h1><p><a href="#/">Read it from the beginning →</a></p></section>`,
 '/discover':()=>`<section class="shell section"><h1>Start here</h1><p><a href="#/">Enter the world →</a></p></section>`,
 '/story':()=>wrapper('The novel in development','The Story',`<p>Approximately two years after an uprising, Elias Varek is still searching for his younger sister Mira. Their bond is loving and imperfect: his need to protect her has never erased her desire for a life of her own.</p><p>Explore the premise and established moments from their lives. These introductions avoid major revelations; they are not excerpts from a finished manuscript.</p><div class="grid">${entries.filter(e=>e.type==='Story').map(e=>card(e)).join('')}</div><a class="text-link" href="#/characters">Meet the wider cast →</a>`),
  '/world':()=>wrapper('Places and institutions','Explore the World',`<p class="muted">Curious about the city's workings? Follow its places, society and history at your own pace.</p><div class="world-paths"><a class="tile" href="#/lore/canyon"><small>Places</small><h3>The Canyon</h3><p>Discover the geography that shapes daily life.</p></a><a class="tile" href="#/lore/upper-access"><small>Society</small><h3>Who Can Cross?</h3><p>Learn how controlled access shapes the city.</p></a><a class="tile" href="#/lore/founding"><small>History</small><h3>The First Crossing</h3><p>How a bridge changed everything.</p></a></div><h2>Explore by subject</h2><div class="grid">${entries.filter(e=>['Geography','District','Society','History','Economy','Everyday life','Places'].includes(e.type)).map(e=>card(e)).join('')}</div>`),
 '/characters':()=>wrapper('People and relationships','Characters',`<p class="muted">Meet the people at the center of the novel’s human story. These introductions intentionally avoid major plot revelations.</p><div class="grid">${entries.filter(e=>e.type==='Character').map(e=>card(e)).join('')}</div>`),
 '/chronology':()=>wrapper('Public historical sequence','Chronology',`<p class="muted">A relative timeline of established, spoiler-safe world history. Follow the crossings and communities that shaped the city.</p><div class="timeline"><div class="event"><h3>The crossing before the city</h3><p>Travelers and merchants face dangerous routes across the canyon.</p></div><div class="event"><h3>A permanent stone crossing</h3><p>Trading families and landholders fund a bridge; tolls and maintenance become sources of influence.</p></div><div class="event"><h3>The growing metropolis</h3><p>Settlements around the crossing expand into one city spanning both rims.</p></div><div class="event"><h3>The Lower City takes root</h3><p>Workers housed near bridges and viaduct works bring families. Migrants, craftspeople and merchants follow; temporary lodgings grow into permanent neighborhoods down the canyon walls.</p></div><div class="event"><h3>The layered modern city</h3><p>A crowded urban society develops beneath the crossings. Its essential work and commerce sustain the metropolis while unequal rights endure.</p></div><div class="event"><h3>The uprising and its aftermath</h3><p>Violence devastates parts of the Lower City. Approximately two years later, Elias is still searching for Mira while inhabited neighborhoods continue their daily lives.</p></div></div><p class="muted">An introduction to the city’s history, without revealing the novel’s plot.</p>`),
 '/lore':()=>wrapper('Search the archives','Lore Archive',`<p class="muted">Go deeper into the people, places, and history behind the illustrated journey.</p><label for="search">Search entries</label><br><input class="search" id="search" type="search" placeholder="Try canyon, river, characters..." autocomplete="off"><div class="filters" id="filters"></div><div class="grid" id="results" aria-live="polite"></div>`),
};
function article(e){const artwork=e.image?`<figure class="journey-art lore-art"><img src="${esc(e.image)}" alt="${esc(e.imageAlt)}" loading="eager" decoding="async"><figcaption>${esc(e.imageCaption||'Concept illustration')} · Developed with AI assistance. Individual visual details remain interpretations. Open full size.</figcaption></figure>`:'';return `<div class="shell article-shell"><p class="muted return-link"><a href="#/lore">← Back to lore archive</a></p>${artwork}${paper(`${e.type} · Public lore`,e.title,`<p><strong>${esc(e.summary)}</strong></p>${e.body.map(x=>`<p>${esc(x)}</p>`).join('')}${related(e)}`)}</div>`}
function render(){let route=(location.hash.slice(1)||'/').replace(/\/$/,'')||'/';const scrollTarget=route.startsWith('read-')?route:null;if(scrollTarget)route='/';const parts=route.split('/').filter(Boolean);let html;if(parts.length===2&&parts[0]==='lore'){const e=entries.find(x=>x.id===parts[1]);html=e?article(e):notFound()}else html=page[route]?page[route]():notFound();app.innerHTML=html;prepareArtworkAccess();const entry=parts.length===2&&parts[0]==='lore'?entries.find(e=>e.id===parts[1]):null;const title=route==='/'?'Where the Light Falls — A Dark Fantasy Novel':(entry?.title||(parts.at(-1)||'World').replaceAll('-',' '))+' — Where the Light Falls';document.title=title;const description=entry?.summary||'Explore Where the Light Falls, a dark fantasy novel in development. Two years after an uprising, Elias searches for Mira in a crowded Gothic canyon city.';document.querySelector('meta[name="description"]').content=description;document.querySelector('meta[property="og:title"]').content=title;document.querySelector('meta[property="og:description"]').content=description;nav.querySelectorAll('a').forEach(a=>{if(route===a.getAttribute('href').slice(1))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});nav.classList.remove('open');document.getElementById('menu').setAttribute('aria-expanded','false');if(route==='/lore')initSearch();if(scrollTarget){requestAnimationFrame(()=>document.getElementById(scrollTarget)?.scrollIntoView({block:'start',behavior:'auto'}))}else window.scrollTo({top:0,behavior:'auto'})}
function notFound(){return wrapper('Not found','This entry is unavailable','<p class="muted">This link may have moved. <a href="#/">Return home</a>.</p>')}
function initSearch(){const input=document.getElementById('search'),results=document.getElementById('results'),filters=document.getElementById('filters');let category='All';const cats=['All',...new Set(entries.map(e=>e.type))];filters.innerHTML=cats.map(t=>`<button type="button" class="filter${t===category?' active':''}" data-filter="${esc(t)}">${esc(t)}</button>`).join('');const update=()=>{const q=input.value.toLocaleLowerCase().trim(),matches=entries.filter(e=>(category==='All'||e.type===category)&&[e.title,e.type,e.summary,...e.body].join(' ').toLowerCase().includes(q));results.innerHTML=matches.length?matches.map(e=>card(e)).join(''):'<p class="muted">No matching public entries.</p>'};filters.addEventListener('click',ev=>{if(ev.target.matches('[data-filter]')){category=ev.target.dataset.filter;filters.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.filter===category));update()}});input.addEventListener('input',update);update()}
document.addEventListener('click',event=>{const link=event.target.closest('a[href^="#read-"]');if(!link)return;const target=document.getElementById(link.getAttribute('href').slice(1));if(target){event.preventDefault();target.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}});
document.getElementById('menu').addEventListener('click',()=>{let open=nav.classList.toggle('open');document.getElementById('menu').setAttribute('aria-expanded',String(open))});
/* Accessible full-resolution illustration viewer: separate from the one-use editorial placements. */
const viewer=document.createElement('dialog');
viewer.className='art-viewer';
viewer.setAttribute('aria-label','Full-size artwork viewer');
viewer.innerHTML='<div class="art-viewer-controls"><span class="art-viewer-label"></span><div class="art-viewer-actions"><button type="button" data-zoom aria-label="Zoom image">Zoom in</button><button type="button" data-close aria-label="Close full-size artwork">Close ✕</button></div></div><div class="art-viewer-stage"><img alt="" draggable="false"></div><p class="art-viewer-hint">Click the image to zoom · Escape to close</p>';
document.body.append(viewer);
let lastFocus=null,zoomed=false;
const photo=viewer.querySelector('img'),zoomButton=viewer.querySelector('[data-zoom]');
function setArtZoom(value){zoomed=value;viewer.classList.toggle('zoomed',value);zoomButton.textContent=value?'Fit image':'Zoom in';zoomButton.setAttribute('aria-label',value?'Fit image to screen':'Zoom image')}
function openArtwork(src,alt){lastFocus=document.activeElement;photo.src=src;photo.alt=alt||'Full-size artwork';viewer.querySelector('.art-viewer-label').textContent=alt||'Illustration';setArtZoom(false);viewer.showModal()}
function closeArtwork(){viewer.close()}
document.addEventListener('click',event=>{const hero=event.target.closest('[data-hero-full]');const img=event.target.closest('.journey-art img');if(hero){openArtwork(hero.dataset.heroFull,'The Grand Crossing — original illustration')}else if(img){openArtwork(img.currentSrc||img.src,img.alt)}});
document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('.journey-art img')){event.preventDefault();openArtwork(event.target.currentSrc||event.target.src,event.target.alt)}});
viewer.querySelector('[data-close]').addEventListener('click',closeArtwork);
zoomButton.addEventListener('click',()=>setArtZoom(!zoomed));
photo.addEventListener('click',()=>setArtZoom(!zoomed));
viewer.addEventListener('click',event=>{if(event.target===viewer)closeArtwork()});
viewer.addEventListener('close',()=>{photo.removeAttribute('src');lastFocus?.focus?.()});
function prepareArtworkAccess(){document.querySelectorAll('.journey-art img').forEach(img=>{img.tabIndex=0;img.setAttribute('role','button');img.setAttribute('aria-label','Open full-size illustration: '+img.alt);img.title='Click to view full size'})}

window.addEventListener('hashchange',render);render();
